import { Controller, HttpCode, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const VIEW_SCOPES = ['전체', '부서', '개인'];
const USE_YNS = ['사용', '미사용'];

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 확인해 주세요.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr02601Controller {
  @Put('/menu-permissions')
  @HttpCode(200)
  async saveMenuPermission(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원');
    const menuId = idOf(data['menuId'], '메뉴');
    const permissionRoleId = idOf(data['permissionRoleId'], '사용 권한 구분');
    const viewScope = String(data['viewScope'] ?? '');
    const useYn = String(data['useYn'] ?? '');
    if (!VIEW_SCOPES.includes(viewScope)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 범위를 확인해 주세요.');
    }
    if (!USE_YNS.includes(useYn)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부를 확인해 주세요.');
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      const menus = await db.query(
        'SELECT menu_id FROM menu WHERE menu_id = CAST(:menuId AS bigint)',
        { menuId },
      );
      const roles = await db.query(
        'SELECT permission_role_id FROM permission_role WHERE permission_role_id = CAST(:roleId AS bigint)',
        { roleId: permissionRoleId },
      );
      if (employees.length === 0 || menus.length === 0 || roles.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_OR_MENU_NOT_FOUND', '대상 사용자 또는 메뉴가 존재하지 않습니다.');
      }
      const existing = await db.query(
        'SELECT menu_permission_id AS "menuPermissionId", view_scope AS "viewScope", use_yn AS "useYn" '
          + 'FROM menu_permission '
          + 'WHERE employee_id = CAST(:employeeId AS bigint) '
          + 'AND menu_id = CAST(:menuId AS bigint) '
          + 'AND permission_role_id = CAST(:roleId AS bigint)',
        { employeeId, menuId, roleId: permissionRoleId },
      );
      let menuPermissionId: number;
      let changeType: string;
      let beforeContent: string | null = null;
      if (existing.length > 0) {
        menuPermissionId = Number(existing[0]['menuPermissionId']);
        changeType = '수정';
        beforeContent = JSON.stringify({
          viewScope: existing[0]['viewScope'],
          useYn: existing[0]['useYn'],
        });
        await db.execute(
          'UPDATE menu_permission SET view_scope = :viewScope, use_yn = :useYn, updated_at = now() '
            + 'WHERE menu_permission_id = CAST(:id AS bigint)',
          { viewScope, useYn, id: String(menuPermissionId) },
        );
      } else {
        changeType = '등록';
        const rows = await db.query(
          'INSERT INTO menu_permission '
            + '(employee_id, menu_id, permission_role_id, view_scope, use_yn, created_at, updated_at) '
            + 'VALUES (CAST(:employeeId AS bigint), CAST(:menuId AS bigint), CAST(:roleId AS bigint), '
            + ':viewScope, :useYn, now(), now()) '
            + 'RETURNING menu_permission_id AS "menuPermissionId"',
          { employeeId, menuId, roleId: permissionRoleId, viewScope, useYn },
        );
        menuPermissionId = Number(rows[0]['menuPermissionId']);
      }
      // 공통 P15: 변경 이력(변경 일시·변경자·변경 내용)을 남긴다.
      await db.execute(
        'INSERT INTO change_history '
          + '(target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) '
          + "VALUES ('menu_permission', CAST(:targetId AS bigint), :changeType, now(), CAST(:userId AS bigint), "
          + ':before, :after, now(), now())',
        {
          targetId: String(menuPermissionId),
          changeType,
          userId: user.id,
          before: beforeContent,
          after: JSON.stringify({ viewScope, useYn }),
        },
      );
      return { menuPermissionId, useYn };
    });
  }
}

