import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  RefName,
  Select,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr02601Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [systemType, setSystemType] = useState('');
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/menu-permissions', role, undefined, { employeeId, systemType, page, size: SIZE }),
    [employeeId, systemType, page],
  );

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const openNew = () => {
    setForm({ useYn: '사용' });
    setOpen(true);
  };

  const openEdit = (row: Row) => {
    setForm({
      employeeId: row['employeeId'],
      menuId: row['menuId'],
      permissionRoleId: row['permissionRoleId'],
      viewScope: row['viewScope'],
      useYn: row['useYn'],
    });
    setOpen(true);
  };

  const save = async () => {
    const missing: string[] = [];
    if (!form['employeeId']) missing.push('임직원');
    if (!form['menuId']) missing.push('메뉴');
    if (!form['permissionRoleId']) missing.push('사용 권한 구분');
    if (!form['viewScope']) missing.push('조회 범위');
    if (!form['useYn']) missing.push('사용 여부');
    if (missing.length > 0) {
      throw new Error('필수 항목을 선택해 주세요: ' + missing.join(', '));
    }
    await call('PUT', '/menu-permissions', role, {
      employeeId: form['employeeId'],
      menuId: form['menuId'],
      permissionRoleId: form['permissionRoleId'],
      viewScope: form['viewScope'],
      useYn: form['useYn'],
    });
    notify('사용 권한을 저장했습니다.');
    setOpen(false);
    reload();
  };

  const rows = data ? data.items : [];

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>권한 건수</h2>
        <Num value={data ? data.total : 0} />
      </section>
      <section className='box span-12'>
        <h2>사용 권한 현황</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            reload();
          }}
          onReset={() => {
            setEmployeeId('');
            setSystemType('');
            setPage(0);
          }}
        >
          <Field label='임직원 ID'>
            <LookupSelect table='employee' role={role} value={employeeId} onChange={(v) => setEmployeeId(v)} />
          </Field>
          <Field label='적용 시스템 구분'>
            <Select
              value={systemType}
              onChange={setSystemType}
              options={[['ERP', 'ERP'], ['그룹웨어', '그룹웨어']]}
              placeholder='전체'
            />
          </Field>
        </Filters>
        {error ? <p>{error}</p> : null}
        <Band total={data ? data.total : 0}>
          <button type='button' onClick={openNew}>권한 설정</button>
        </Band>
        <DataTable
          rows={rows}
          onRowClick={openEdit}
          empty='조회된 사용 권한이 없습니다.'
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
            { key: 'menuId', label: '메뉴 ID', render: (r) => <RefName table='menu' role={role} value={r['menuId']} /> },
            { key: 'permissionRoleId', label: '사용 권한 구분 ID', render: (r) => <RefName table='permission_role' role={role} value={r['permissionRoleId']} /> },
            { key: 'viewScope', label: '조회 범위' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {open ? (
        <Drawer title='사용 권한 설정' onClose={() => setOpen(false)}>
          <Form onSubmit={save} submit='저장'>
            <Field label='임직원 ID' required>
              <LookupSelect table='employee' role={role} value={form['employeeId']} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label='메뉴 ID' required>
              <LookupSelect table='menu' role={role} value={form['menuId']} onChange={(v) => set('menuId', v)} />
            </Field>
            <Field label='사용 권한 구분 ID' required>
              <LookupSelect table='permission_role' role={role} value={form['permissionRoleId']} onChange={(v) => set('permissionRoleId', v)} />
            </Field>
            <Field label='조회 범위' required>
              <Select
                value={form['viewScope']}
                onChange={(v) => set('viewScope', v)}
                options={[['전체', '전체'], ['부서', '부서'], ['개인', '개인']]}
              />
            </Field>
            <Field label='사용 여부' required>
              <Select
                value={form['useYn']}
                onChange={(v) => set('useYn', v)}
                options={[['사용', '사용'], ['미사용', '미사용']]}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
